const NIV={1:['b1','b2','p1'],2:['b1','b2','p1','p2'],3:['p1','p2','a1'],4:['p1','p2','a1','a2'],5:['p2','a1','a2']};
const cod=s=>`<pre><code>${s.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</code></pre>`;
const qcod=(q,c)=>`${q}${cod(c)}`;
const sum=a=>a.reduce((s,x)=>s+x,0);
const KC=(items,o={})=>KES.paso(items,{que:'Sigue el código línea por línea',como:it=>'Lee cada instrucción y lleva la cuenta de las variables.',porque:'Ejecutar el código «a mano» es la mejor forma de entenderlo.',...o});

